#!/usr/bin/env python3
from pathlib import Path
import json,datetime,urllib.request,hashlib
HOME=Path.home()/'.dore'/'design'; WS=HOME/'westside-watch.workspace.json'; HIST=HOME/'workspace-history'; HIST.mkdir(parents=True,exist_ok=True)
w=json.loads(WS.read_text()); rev=int(w.get('revision',1)); now=datetime.datetime.now(datetime.timezone.utc).isoformat()
if WS.exists(): (HIST/f'westside-watch.r{rev:05d}.json').write_text(json.dumps(w,ensure_ascii=False,indent=2))
def t(i,text,x,y,width,size,**k): return {'id':i,'type':'text','text':text,'x':x,'y':y,'w':width,'size':size,**k}
def r(i,x,y,width,h=1): return {'id':i,'type':'rule','x':x,'y':y,'w':width,'h':h}
def b(i,x,y,width,h,ey,title,body): return {'id':i,'type':'block','x':x,'y':y,'w':width,'h':h,'eyebrow':ey,'title':title,'body':body}
common=t('brand','WESTSIDE WATCH · 西望',42,28,420,18)
families=[]
def add(pid,name,hyp,why,learn,reject,risk,nodes):
 families.append({'id':pid,'name':'New Westside · '+name,'canvas':{'w':1440,'h':1000},'experimental_only':True,'product_acceptance':False,'style_acceptance':False,'design_family':name,'rationale':{'hypothesis':hyp,'why_test':why,'prior_learning_consumed':learn,'deliberately_rejected':reject,'largest_risk':risk},'nodes':[common]+nodes+[t(pid+'-reason','WHY THIS EXISTS\n'+why,1010,850,360,14)]})
add('new-westside-archive-broadsheet','Archive Broadsheet','Westside can feel like a living edited record rather than a landing page.','Tests whether editorial density creates stronger identity than a monumental hero.','Real destinations, bilingual hierarchy, hierarchy before atmosphere.','Giant-serif hero as the sole identity device; equal destination cards.','Density may feel archival rather than alive.',[t('ab-date','VOL. I · WATCH FOR THE DAWN · ROM 13:12',900,30,480,14),r('ab-top',30,62,1380),t('ab-head','THE WESTSIDE\nWATCH',42,92,720,92),t('ab-zh','守望，一座光明的城',790,120,520,42),r('ab-mid',30,310,1380),b('ab-lead',42,350,620,470,'LEAD / JOURNAL','01 JOURNAL','文章、見證與西區的夜晚'),b('ab-one',700,350,300,220,'SCRIPTURE','02 ONE','逐卷逐章查考聖經'),b('ab-church',1030,350,350,220,'ASSEMBLY','03 LIVING WATER WEST','教會生活與聚會'),t('ab-low','04 黎明書局     05 THE GATE',700,650,650,34)])
add('new-westside-stone-threshold','Stone Threshold','The homepage should behave like crossing a physical threshold into a place.','Tests spatial and material identity instead of dashboard navigation.','Watchtower threshold-city insight; destinations as procession.','Flat editorial columns and equal cards.','Architectural metaphor may overpower content.',[b('st-wall',40,105,850,720,'THRESHOLD / 石','ENTER THE WATCH','黑夜已深，白晝將近。'),t('st-title','A DOOR\nBEFORE\nMORNING',95,190,650,86),r('st-axis',930,110,4,720),t('st-path','01 JOURNAL',970,150,360,34),t('st-path2','02 ONE',1030,290,300,34),t('st-path3','03 LIVING WATER WEST',950,430,420,30),t('st-path4','04 黎明書局',1040,570,300,34),t('st-path5','05 THE GATE',970,710,320,34),t('st-zh','進入西區守望',70,850,500,44)])
add('new-westside-field-notes','Field Notes','Local observation, notes and documentary fragments can make Westside more specific and human.','Tests identity through evidence and locality rather than luxury editorial atmosphere.','Need for documentary/local material and real-content stress.','Monumental polish, symmetrical prestige, abstract darkness.','May look intentionally unfinished without future imagery.',[t('fn-label','FIELD NOTES / VAUGHAN · TORONTO',42,95,500,15),t('fn-title','WHAT WE SAW\nBEFORE DAWN',42,145,600,68),b('fn-note1',720,100,610,250,'NOTE 01 / JOURNAL','守望，一座光明的城','本月記錄 · 人 · 地方 · 見證'),t('fn-margin','03 SEP\n21:12\nWESTSIDE',650,390,120,16),b('fn-note2',90,500,430,260,'NOTE 02','ONE','查經前哨站 · 背景 · 地圖 · 串珠'),b('fn-note3',600,500,330,260,'NOTE 03','LIVING WATER WEST','聚會與教會生活'),b('fn-note4',1010,500,330,260,'NOTES 04–05','黎明書局 / THE GATE','研究資源 · 進入'),r('fn-rule',42,820,1290),t('fn-verse','THE DAY IS AT HAND.',42,850,700,50)])
add('new-westside-liturgical-sequence','Liturgical Sequence','Navigation can become a meaningful sequence: watch, read, remember, gather, enter.','Tests narrative information architecture as the design itself.','Destinations should have hierarchy and narrative, not equal buttons.','Dashboard scanning and simultaneous five-way choice.','Sequence may imply a required order where none exists.',[t('ls-title','A WAY THROUGH\nTHE NIGHT',42,100,600,76),t('ls-zh','從守望，到進入',850,120,450,42),r('ls-spine',710,230,4,620),t('ls-1','I  WATCH\nJOURNAL · 守望',120,260,500,42),t('ls-2','II  READ\nONE · 查經',790,370,500,42),t('ls-3','III  REMEMBER\n黎明書局 · 閱讀',120,480,500,42),t('ls-4','IV  GATHER\nLIVING WATER WEST · 聚集',790,590,550,38),t('ls-5','V  ENTER\nTHE GATE · 進入',120,700,500,42),t('ls-end','THE NIGHT IS FAR SPENT.',790,850,520,28)])
add('new-westside-luminous-index','Luminous Index','Westside identity may survive without dark green, stone and gold atmosphere.','Tests whether clarity, light and indexing can carry the brand and prevent premature aesthetic lock-in.','Semantic spine, readable destinations, reduced auxiliary density.','Dark monumental mood, architectural metaphor, decorative material.','May become too neutral or institutional.',[t('li-no','INDEX 01—05',42,100,300,14),t('li-title','WATCH FOR\nTHE DAWN.',42,145,600,82),t('li-zh','西區守望',980,155,300,46),r('li-a',42,350,1300),t('li-1','01',42,390,80,28),t('li-1b','JOURNAL / 守望，一座光明的城',180,385,1050,38),r('li-b',42,470,1300),t('li-2','02',42,510,80,28),t('li-2b','ONE / 逐卷逐章查考聖經',180,505,1050,38),r('li-c',42,590,1300),t('li-3','03',42,630,80,28),t('li-3b','LIVING WATER WEST / 教會生活',180,625,1050,38),r('li-d',42,710,1300),t('li-45','04  黎明書局                         05  THE GATE',42,760,1200,32)])
ids={p['id'] for p in families}; w['pages']=[p for p in w.get('pages',[]) if p.get('id') not in ids]+families; w['revision']=rev+1; w['updated_at']=now
tmp=WS.with_suffix('.tmp'); tmp.write_text(json.dumps(w,ensure_ascii=False,indent=2)); tmp.replace(WS)
checks=[]
for p in families:
 for route in ('preview/'+p['id'],'api/export.html?page='+p['id']):
  u='http://127.0.0.1:4310/'+route
  with urllib.request.urlopen(u,timeout=10) as q: data=q.read(); checks.append({'page':p['id'],'route':route,'status':q.status,'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)})
 a=checks[-2]; z=checks[-1]; assert a['status']==200 and z['status']==200 and a['sha256']==z['sha256']
print(json.dumps({'ok':True,'code':'NEW_WESTSIDE_FIVE_FAMILY_EDITOR_ROUND_PASS','revision':w['revision'],'families':[{'id':p['id'],'name':p['design_family'],'rationale':p['rationale'],'node_count':len(p['nodes'])} for p in families],'checks':checks},ensure_ascii=False))
